function auditKafkaClusterTopology(cluster) {
  const brokerHealth = cluster.brokers.every(b => b.status === 'ONLINE');
  const topicStats = {};
  for (const topic of cluster.topics) {
    const isReplicated = topic.replicationFactor >= 2;
    topicStats[topic.name] = {
      partitions: topic.partitionCount,
      replicated: isReplicated,
      status: isReplicated ? 'HEALTHY' : 'UNDER_REPLICATED'
    };
  }
  return {
    clusterId: cluster.clusterId,
    allBrokersOnline: brokerHealth,
    topicsAudited: Object.keys(topicStats).length,
    topicStats
  };
}

