function assignKafkaPartitionByKey(key, partitionCount) {
  let hash = 0;
  for (let i = 0; i < key.length; i++) {
    hash = (hash * 31 + key.charCodeAt(i)) >>> 0;
  }
  const partition = hash % partitionCount;
  return {
    key,
    hashValue: hash,
    partition,
    partitionCount
  };
}

const key1 = assignKafkaPartitionByKey('user_1024', 6);
const key2 = assignKafkaPartitionByKey('user_1025', 6);
const key3 = assignKafkaPartitionByKey('user_1024', 6); // Consistent hashing check

