console.log('Consistent Assignment:', key1.partition === key3.partition);
console.log('Partition In Range:', key1.partition >= 0 && key1.partition < 6);

function rebalanceConsumerGroup(consumers, partitionCount) {
  const assignment = {};
  for (const c of consumers) assignment[c] = [];

  for (let p = 0; p < partitionCount; p++) {
    const consumerIdx = p % consumers.length;
    assignment[consumers[consumerIdx]].push(p);
  }

  return {
    consumerCount: consumers.length,
    totalPartitions: partitionCount,
    assignment
  };
}

