function evaluateOffsetCommit(mode, lastProcessedOffset, committedOffset) {
  let lag = 0;
  let risk = 'NONE';

  if (mode === 'AT_LEAST_ONCE') {
    lag = lastProcessedOffset - committedOffset;
    risk = 'POTENTIAL_DUPLICATES_ON_CRASH';
  } else if (mode === 'AT_MOST_ONCE') {
    lag = 0;
    risk = 'POTENTIAL_DATA_LOSS_ON_CRASH';
  } else if (mode === 'EXACTLY_ONCE') {
    lag = 0;
    risk = 'ZERO_LOSS_ZERO_DUPLICATES';
  }

  return {
    mode,
    lastProcessedOffset,
    committedOffset,
    lag,
    risk
  };
}

const atLeastOnce = evaluateOffsetCommit('AT_LEAST_ONCE', 1050, 1045);
const exactlyOnce = evaluateOffsetCommit('EXACTLY_ONCE', 1050, 1050);

console.log('Commit Mode:', atLeastOnce.mode);
console.log('Uncommitted Lag:', atLeastOnce.lag);
console.log('Failure Risk:', atLeastOnce.risk);
console.log('Exactly Once Guarantee:', exactlyOnce.risk);

function monitorKafkaConsumerLag(partitions) {
  let totalLag = 0;
  let maxLag = 0;
  let criticalPartitions = 0;

  for (const p of partitions) {
    const lag = p.logEndOffset - p.currentOffset;
    totalLag += lag;
    if (lag > maxLag) maxLag = lag;
    if (lag > 1000) criticalPartitions++;
  }

  return {
    partitionCount: partitions.length,
    totalLag,
    maxLag,
    criticalPartitions,
    isHealthy: totalLag < 5000 && criticalPartitions === 0
  };
}

const lagReport = monitorKafkaConsumerLag([
  { partition: 0, logEndOffset: 120500, currentOffset: 120480 },
  { partition: 1, logEndOffset: 115200, currentOffset: 115150 },
  { partition: 2, logEndOffset: 140000, currentOffset: 139985 }
]);

console.log('Total Consumer Lag:', lagReport.totalLag);
